use std::net::SocketAddr;
use tokio::sync::oneshot;

// Include prost message types and native service stubs generated by build.rs
// from tests/proto/greeter.proto.
//
// greeter.rs        → HelloRequest / HelloReply (prost messages, via tonic-prost-build)
// greeter.services.rs → greeter_server / greeter_client modules (native oxirpc-build stubs)
pub mod greeter {
    include!(concat!(env!("OUT_DIR"), "/greeter.rs"));
    include!(concat!(env!("OUT_DIR"), "/greeter.services.rs"));
}

use greeter::{
    greeter_client::GreeterClient,
    greeter_server::{Greeter, GreeterServer},
    HelloReply, HelloRequest,
};

#[derive(Debug, Default)]
struct MyGreeter;

#[tonic::async_trait]
impl Greeter for MyGreeter {
    async fn hello(
        &self,
        request: tonic::Request<HelloRequest>,
    ) -> Result<tonic::Response<HelloReply>, tonic::Status> {
        let name = request.into_inner().name;
        let reply = HelloReply {
            message: format!("hello, {name}"),
        };
        Ok(tonic::Response::new(reply))
    }
}

#[tokio::test]
async fn greeter_round_trip() {
    let addr: SocketAddr = "127.0.0.1:0".parse().expect("addr parse");
    let listener = tokio::net::TcpListener::bind(addr).await.expect("bind");
    let port = listener.local_addr().expect("local_addr").port();
    let (tx, rx) = oneshot::channel::<()>();

    let server = tokio::spawn(async move {
        tonic::transport::Server::builder()
            .add_service(GreeterServer::new(MyGreeter))
            .serve_with_incoming_shutdown(
                tokio_stream::wrappers::TcpListenerStream::new(listener),
                async {
                    rx.await.ok();
                },
            )
            .await
            .ok();
    });

    // Give server a moment to start accepting.
    tokio::time::sleep(std::time::Duration::from_millis(50)).await;

    let channel = tonic::transport::Channel::from_shared(format!("http://127.0.0.1:{port}"))
        .expect("channel build")
        .connect()
        .await
        .expect("connect");

    let mut client = GreeterClient::new(channel);
    let req = tonic::Request::new(HelloRequest {
        name: "world".to_string(),
    });
    let resp = client.hello(req).await.expect("rpc failed");
    assert_eq!(resp.into_inner().message, "hello, world");

    tx.send(()).ok();
    server.await.ok();
}
